import {getAction} from '@madou/catalog';
import {allCardInstanceIds,createGame,gameStats,transition,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand} from './scenario-tools.js';
export const closeEarthPhysicalScenarios=['dragon-close','earth-pair','dragon-close-teleport','earth-pair-teleport'] as const;
export type CloseEarthPhysicalScenario=typeof closeEarthPhysicalScenarios[number];
export function isCloseEarthPhysicalScenario(name:string):name is CloseEarthPhysicalScenario{return (closeEarthPhysicalScenarios as readonly string[]).includes(name);}
export function closeEarthPhysicalMode(name:CloseEarthPhysicalScenario){const dragon=name.startsWith('dragon');return{dragon,teleport:name.endsWith('-teleport'),card:dragon?'a2-p18-r1c2':'a2-p18-r1c3',name:dragon?'紋竜破':'地裂',damage:dragon?15:8};}
export function makeCloseEarthPhysicalScenario(name:CloseEarthPhysicalScenario,players:{id:string;name:string}[],options:{level?:number;none?:boolean;royal?:boolean;ship?:boolean}={}){
 const m=closeEarthPhysicalMode(name);let s=createGame(players,entropy(),{startingSeat:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];for(const [i,p] of players.entries())assignCharacter(s,p.id,['白魔術師シェリム','魔導王ガイナス','魔聖母ディア','侍大将のシン'][i]!);for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit=20+6-gameStats(s,p.id).spirit;}s.players[a]!.permanent!.magic_level=20+(options.level??6)-gameStats(s,a).magic_level;
 const front=options.none?null:takeCard(s,b,options.royal?'王立騎士団':options.ship?'歌う船':'ストーンゴーレム'),rear=options.none||options.royal?null:takeCard(s,b,'兵士'),metal=options.none?null:takeCard(s,c,'メタルゴーレム'),keep=[takeCard(s,a,m.card),takeCard(s,a,'a2-p24-r1c2'),takeCard(s,a,'必勝の祈り'),takeCard(s,d,'命運凶変'),...[front,rear,metal].filter((x):x is string=>!!x),...(m.teleport?['a2-p06-r1c1','a2-p05-r3c1','a2-p07-r1c1']:['a2-p14-r2c3','a2-p11-r1c3','a2-p12-r3c2']).map(id=>takeCard(s,b,id))];for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];
 function act(actorId:string,command:GameCommand){const input={actorId,command},e={...entropy(),dice:Array(100).fill(1)},r=transition(s,input,e);if(!r.ok)throw Error(`CLOSE_EARTH_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('CLOSE_EARTH_JSON');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('CLOSE_EARTH_IDS');}
 for(const p of players){for(const cardInstanceId of (p.id===b?[front,rear]:p.id===c?[metal]:[]).filter((x):x is string=>!!x))act(p.id,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId});act(p.id,{type:'PASS_SETUP'});}act(a,{type:'START_TURN'});act(a,{type:'CHOOSE_DRAW',draw:false});return s;
}
